fn shell_dhcp_client() -> &'static str {
    r####"    // The identity binding is the root object: one MAC-keyed roster feeds every perspective.
    const identityState = { roster: [], boundary: {}, dhcpBoundary: {}, dhcpBoundaryCommitted: 0, leases: [], reservations: [], dns: {}, notes: {}, modalMac: null, anonymized: false, reservation: null };
    const identityPerspective = Object.freeze({
      address: Object.freeze({ lead: ['MAC', 'Observed lease', 'Declared reservation'], emphasis: 'address', writable: true }),
      name: Object.freeze({ lead: ['MAC', 'Names', 'Claim state'], emphasis: 'name', writable: true }),
      liveness: Object.freeze({ lead: ['MAC', 'Last activity', 'Observed IP'], emphasis: 'liveness', writable: false, notes: true }),
    });
    const identityText = value => String(value ?? '—');
    const identityRows = payload => Array.isArray(payload) ? payload : (payload?.devices || payload?.roster || payload?.data?.devices || []);
    async function identityJson(route, options = {}) { const response = await fetch(route, { cache: 'no-store', headers: options.body ? {'content-type':'application/json'} : {}, ...options }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.first_failing_boundary || body.firstMissingSignal || body.error || `Request failed (${response.status})`); return body; }
    function identityIp(row, key) { return row?.[key]?.ip || '—'; }
    // Retains the former DHCP privacy grammar on the single shared roster.
    function dhcpMasked(value, kind) { const raw = String(value || '—'); if (!identityState.anonymized) return escapeHtml(raw); if (kind === 'mac') return raw.split(':').map((part, index) => index < 3 ? part : '••').join(':'); if (kind === 'ip') return raw.replace(/\.\d+$/, '.•••'); return raw ? 'Private device' : '—'; }
    function identityReservation(row) { const reservation = row?.declared_reservation; if (!reservation || typeof reservation !== 'object') return null; const id = reservation.id || reservation.reservationId || reservation.reservation_id || row.reservation_id || row.reservationId || row.mac; return id ? { id: String(id), ip: reservation.ip || reservation['ip-address'] || reservation.ipAddress || '' } : null; }
    function identityLastActivity(row) { return row?.observed_lease?.last_activity || row?.observed_lease?.lastActivity || row?.observed_lease?.hostname || row?.last_activity || row?.lastActivity || '—'; }
    function identityRosterMarkup(row, perspective) { const cfg = identityPerspective[perspective]; const names = (row.dns_names || []).join(', ') || '—'; const marks = (row.mismatches || []).map(identityText).join(', ') || 'None'; const observed = identityIp(row, 'observed_lease'); const declared = identityIp(row, 'declared_reservation'); if (!cfg.writable) { const canonicalMac = canonicalNetworkNoteMac(row.mac), note = canonicalMac ? identityState.notes[canonicalMac] ?? '' : '', pencil = headerState.isAdmin ? `<button type="button" class="edit-note-button" data-edit-note-button data-mac="${escapeHtml(row.mac)}" data-note="${escapeHtml(note)}" title="Edit device note" aria-label="Edit note for ${escapeHtml(row.mac)}"><i class="fas fa-pencil-alt" aria-hidden="true"></i></button>` : ''; return `<tr data-device-mac="${escapeHtml(row.mac)}" data-roster-emphasis="${cfg.emphasis}"><td><code>${dhcpMasked(row.mac, 'mac')}</code></td><td>${dhcpMasked(identityLastActivity(row), 'hostname')}</td><td>${dhcpMasked(observed, 'ip')}</td><td>${dhcpMasked(names, 'hostname')}</td><td class="device-note-cell" data-label="Note:"><span class="note-text" data-note-text data-mac="${escapeHtml(row.mac)}">${dhcpMasked(note, 'hostname')}</span>${pencil}</td><td>${escapeHtml(row.claim_state || 'unclaimed')}</td><td>${escapeHtml(marks)}</td></tr>`; } const reservation = identityReservation(row); if (perspective === 'address') { const state = reservation ? `<span class="dhcp-pin-badge" aria-label="Pinned address">Pinned</span>` : '<span class="dhcp-unpinned-state">Available to pin</span>'; const action = reservation ? `<button type="button" class="ui-button ui-button--secondary ui-button--small" data-dhcp-edit="${escapeHtml(reservation.id)}" data-dhcp-ip="${escapeHtml(reservation.ip)}">Edit</button><button type="button" class="ui-button ui-button--danger ui-button--small" data-dhcp-remove="${escapeHtml(reservation.id)}">Unreserve</button>` : `<button type="button" class="ui-button ui-button--primary ui-button--small" data-dhcp-pin="${escapeHtml(row.mac)}">Pin</button>`; return `<tr class="dhcp-device-row ${reservation ? 'dhcp-device-row--pinned' : 'dhcp-device-row--lease'}" data-device-mac="${escapeHtml(row.mac)}"><td><code>${dhcpMasked(row.mac, 'mac')}</code></td><td>${dhcpMasked(observed, 'ip')}</td><td>${dhcpMasked(declared, 'ip')}</td><td>${dhcpMasked(names, 'hostname')}</td><td>${state}</td><td class="dhcp-device-actions">${action}</td></tr>`; } const lead = names; const action = reservation ? `<button type="button" class="ui-button ui-button--secondary ui-button--small" data-dhcp-edit="${escapeHtml(reservation.id)}" data-dhcp-ip="${escapeHtml(reservation.ip)}">Edit</button><button type="button" class="ui-button ui-button--danger ui-button--small" data-dhcp-remove="${escapeHtml(reservation.id)}">Remove</button>` : `<button type="button" class="ui-button ui-button--primary ui-button--small" data-identity-claim="${escapeHtml(row.mac)}">Claim</button>`; return `<tr data-device-mac="${escapeHtml(row.mac)}" data-roster-emphasis="${cfg.emphasis}"><td><code>${dhcpMasked(row.mac, 'mac')}</code></td><td>${dhcpMasked(lead, 'hostname')}</td><td>${dhcpMasked(observed, 'ip')}</td><td>${dhcpMasked(declared, 'ip')}</td><td>${dhcpMasked(names, 'hostname')}</td><td>${escapeHtml(row.claim_state || 'unclaimed')}</td><td>${escapeHtml(marks)}</td><td>${action}</td></tr>`; }
    // This is deliberately the sole roster renderer; tabs differ only by the perspective argument.
    function renderIdentityRoster(perspective) { document.querySelectorAll(`[data-identity-roster-host][data-identity-perspective="${perspective}"] [data-identity-roster]`).forEach(target => { const cfg = identityPerspective[perspective]; const isDhcpAddress = perspective === 'address'; const headings = isDhcpAddress ? '<th>MAC</th><th>Observed lease</th><th>Declared reservation</th><th>DNS names</th><th>Status</th><th>Action</th>' : cfg.writable ? `<th>${cfg.lead[0]}</th><th>${cfg.lead[1]}</th><th>Observed lease</th><th>Declared reservation</th><th>DNS names</th><th>${cfg.lead[2]}</th><th>Mismatches</th><th>Action</th>` : `<th>${cfg.lead[0]}</th><th>${cfg.lead[1]}</th><th>${cfg.lead[2]}</th><th>Names</th><th>Note</th><th>Claim state</th><th>Mismatches</th>`; const columns = isDhcpAddress ? 6 : cfg.writable ? 8 : 7; const tableClass = isDhcpAddress ? 'identity-roster dhcp-device-table' : 'identity-roster'; target.innerHTML = `<table class="${tableClass}"><thead><tr>${headings}</tr></thead><tbody>${identityState.roster.map(row => identityRosterMarkup(row, perspective)).join('') || `<tr><td colspan="${columns}">No devices reported.</td></tr>`}</tbody></table>`; }); }
    function nextFreeIp() { const used = new Set([...identityState.leases, ...identityState.reservations].map(row => String(row.ip || row['ip-address'] || row.ipAddress || ''))); const boundary = identityState.boundary?.boundary || identityState.boundary || {}; const start = String(boundary.start || boundary.first || boundary.pool_start || ''); const end = String(boundary.end || boundary.last || boundary.pool_end || ''); const n = ip => ip.split('.').reduce((acc, part) => acc * 256 + Number(part), 0); const dotted = value => [24,16,8,0].map(shift => (value >>> shift) & 255).join('.'); if (!/^\d+(\.\d+){3}$/.test(start) || !/^\d+(\.\d+){3}$/.test(end)) return ''; for (let value=n(start); value<=n(end); value++) { const ip=dotted(value); if (!used.has(ip)) return ip; } return ''; }
    function openIdentityClaim(mac) { const row = identityState.roster.find(item => item.mac === mac); if (!row) return; identityState.modalMac = row.mac; const modal = document.querySelector('[data-identity-claim-modal]'); const body = document.querySelector('[data-identity-claim-body]'); const suggested = nextFreeIp(); const taken = [...new Set([...identityState.leases, ...identityState.reservations].map(row => row.ip || row['ip-address'] || row.ipAddress).filter(Boolean))]; body.innerHTML = `<p>MAC <code>${escapeHtml(row.mac)}</code> is fixed from this roster row.</p><label>Hostname<input class="ui-input ui-input--medium" data-identity-hostname value="${escapeHtml((row.dns_names || [])[0]?.split('.')[0] || '')}"></label><label>Reserved IP <input class="ui-input ui-input--medium" data-identity-ip value="${escapeHtml(suggested)}" placeholder="${escapeHtml(suggested || 'Staff selects automatically')}"></label><p>Suggested next free: <strong>${escapeHtml(suggested || 'staff decides')}</strong></p><p>Taken: ${escapeHtml(taken.join(', ') || 'none')}</p><p data-identity-claim-result aria-live="polite"></p>`; modal.classList.add('open'); modal.setAttribute('aria-hidden','false'); }
    function closeIdentityClaim() { const modal=document.querySelector('[data-identity-claim-modal]'); modal?.classList.remove('open'); modal?.setAttribute('aria-hidden','true'); }
    function closeIdentityReservation() { const modal=document.querySelector('[data-identity-reservation-modal]'); modal?.classList.remove('open'); modal?.setAttribute('aria-hidden','true'); identityState.reservation=null; }
    function openIdentityReservation(mode, id, ip) { identityState.reservation={mode,id}; const modal=document.querySelector('[data-identity-reservation-modal]'); const title=document.querySelector('[data-identity-reservation-title]'); const body=document.querySelector('[data-identity-reservation-body]'); const save=document.querySelector('[data-identity-reservation-save]'); title.textContent=mode === 'edit' ? 'Edit reserved address' : 'Remove reservation'; body.innerHTML=mode === 'edit' ? `<label>Reserved IP <input class="ui-input ui-input--medium" data-identity-reservation-ip value="${escapeHtml(ip || '')}"></label>` : '<p>Remove this reserved address?</p>'; save.textContent=mode === 'edit' ? 'Save' : 'Remove'; modal.classList.add('open'); modal.setAttribute('aria-hidden','false'); body.querySelector('input')?.focus(); }
    async function saveIdentityReservation() { const reservation=identityState.reservation; if (!reservation) return; const route='/api/dhcp/reservations/' + encodeURIComponent(reservation.id); const body=reservation.mode === 'edit' ? {ip: document.querySelector('[data-identity-reservation-ip]')?.value.trim()} : undefined; if (reservation.mode === 'edit' && !body.ip) return; try { await identityJson(route, {method: reservation.mode === 'edit' ? 'PUT' : 'DELETE', body: body === undefined ? undefined : JSON.stringify(body)}); showCoronatioToast(reservation.mode === 'edit' ? 'Reservation updated.' : 'Reservation removed.', 'success'); closeIdentityReservation(); await hydrateIdentity(); } catch (failure) { showCoronatioToast(failure?.message || 'DHCP request failed', 'error'); } }
    async function saveIdentityClaim() { const mac = identityState.modalMac; const hostname = document.querySelector('[data-identity-hostname]')?.value.trim(); const ip = document.querySelector('[data-identity-ip]')?.value.trim(); if (!mac || !hostname) return; const payload = ip ? {mac, ip, hostname} : {mac, autoIp:true, hostname}; const result = document.querySelector('[data-identity-claim-result]'); result.textContent='Saving…'; try { const receipt=await identityJson('/api/network/device/claim',{method:'POST',body:JSON.stringify(payload)}); const state=receipt.state || receipt.data?.state; const boundary=receipt.first_failing_boundary || receipt.data?.first_failing_boundary; result.textContent=(state === 'applied' || state === 'noop') ? (state === 'noop' ? 'Already current.' : 'Applied.') : `${state || 'blocked'}${boundary ? `: ${boundary}` : ''}`; if (state === 'applied' || state === 'noop') { showCoronatioToast(state === 'noop' ? 'Device already current.' : 'Device claim applied.', 'success'); await hydrateIdentity(); } else showCoronatioToast(result.textContent, 'error'); } catch (failure) { result.textContent=`blocked: ${failure.message}`; showCoronatioToast(result.textContent,'error'); } }
    async function pinDhcpLease(mac) { if (!mac) return; try { await identityJson('/api/dhcp/reservations',{method:'POST',body:JSON.stringify({mac})}); showCoronatioToast('Pinned to the next available reserved address.', 'success'); await hydrateIdentity(); } catch (failure) { showCoronatioToast(failure?.message || 'DHCP pin request failed', 'error'); } }
    const dhcpNumber = value => Number.isFinite(Number(value)) ? Number(value) : 0;
    function dhcpText(selector, value) { document.querySelectorAll(selector).forEach(target => { target.textContent=String(value); }); }
    function paintDhcpBoundary(statistics, boundary) { const reservations=dhcpNumber(statistics?.reservations_count); const leases=dhcpNumber(statistics?.leases_count); const minValue=reservations; const maxValue=leases === 0 ? 249 : 249 - leases; const configured=dhcpNumber(boundary?.max_reservations); const value=Math.min(maxValue, Math.max(minValue, configured)); identityState.dhcpBoundary=boundary || {}; identityState.dhcpBoundaryCommitted=value; dhcpText('[data-dhcp-homeserver]', statistics?.homeserver_ip ?? '—'); dhcpText('[data-dhcp-reservations-count]', reservations); dhcpText('[data-dhcp-hosts-count]', reservations + leases); dhcpText('[data-dhcp-leases-count]', leases); dhcpText('[data-dhcp-boundary-min]', minValue); dhcpText('[data-dhcp-boundary-max]', maxValue); dhcpText('[data-dhcp-boundary-value]', value); document.querySelectorAll('[data-dhcp-boundary]').forEach(slider => { slider.min=String(minValue); slider.max=String(maxValue); slider.value=String(value); }); }
    async function hydrateDhcpBoundary() { const [statistics,boundary]=await Promise.all([identityJson('/api/dhcp/statistics'),identityJson('/api/dhcp/pool-boundary')]); paintDhcpBoundary(statistics,boundary); }
    function hydrateDhcp() { return hydrateIdentity(); }
    async function hydrateIdentity() { if (!viewportFamilyAdmitted('dhcp') && !viewportFamilyAdmitted('unbound')) return; try { const [roster,boundary,leases,reservations,dns]=await Promise.all([identityJson('/api/network/device'),identityJson('/api/network/dhcp/boundary'),identityJson('/api/network/dhcp/leases'),identityJson('/api/network/dhcp/reservations'),identityJson('/api/network/dns/read')]); identityState.roster=identityRows(roster); identityState.boundary=boundary; identityState.leases=identityRows(leases); identityState.reservations=identityRows(reservations); identityState.dns=dns; if (viewportFamilyAdmitted('dhcp')) await hydrateDhcpBoundary(); renderIdentityRoster('address'); renderIdentityRoster('name'); renderDnsNames(); const loading=document.querySelector('[data-dhcp-loading]'); if (loading) loading.hidden=true; } catch (failure) { const error=document.querySelector('[data-dhcp-error]'); if(error) {error.hidden=false;error.textContent=`Network identity unavailable: ${failure.message}`;} } }
    function renderDnsNames() { const target=document.querySelector('[data-dns-names]'); if (!target) return; const aliases=identityState.dns.aliases || identityState.dns.cnames || []; target.innerHTML=`<h3>Names</h3><p>Device A/PTR rows are projections; claim changes them.</p><ul>${aliases.map(item=>`<li>${escapeHtml(item.name || item.alias || '')} → ${escapeHtml(item.target || item.cname || '')}</li>`).join('') || '<li>No DNS-only aliases.</li>'}</ul><button type="button" class="ui-button ui-button--secondary ui-button--small" disabled title="Alias write route is not available">Alias editing unavailable: Caduceus route pending</button>`; }
    document.addEventListener('change', event => { const anonymize=event.target.closest?.('[data-dhcp-anonymize]'); if (anonymize) { identityState.anonymized=anonymize.checked; renderIdentityRoster('address'); renderIdentityRoster('name'); } },true);
    document.addEventListener('input', event => { const slider=event.target.closest?.('[data-dhcp-boundary]'); if (slider) dhcpText('[data-dhcp-boundary-value]', slider.value); },true);
    document.addEventListener('click', async event => { const saveBoundary=event.target.closest?.('[data-dhcp-boundary-save]'); if (saveBoundary) { const slider=document.querySelector('[data-dhcp-boundary]'); if (!slider) return; try { const receipt=await identityJson('/api/dhcp/pool-boundary',{method:'POST',body:JSON.stringify({max_reservations: Number(slider.value)})}); if (receipt?.success === false || receipt?.ok === false) throw new Error(receipt?.error || receipt?.firstMissingSignal || 'DHCP boundary was not applied'); await hydrateDhcpBoundary(); showCoronatioToast('Reserved-address boundary applied.', 'success'); } catch (failure) { slider.value=String(identityState.dhcpBoundaryCommitted); dhcpText('[data-dhcp-boundary-value]', identityState.dhcpBoundaryCommitted); showCoronatioToast(failure?.message || 'DHCP boundary request failed', 'error'); } return; } const pin=event.target.closest?.('[data-dhcp-pin]'); if(pin) return pinDhcpLease(pin.dataset.dhcpPin); const claim=event.target.closest?.('[data-identity-claim]'); if(claim) return openIdentityClaim(claim.dataset.identityClaim); const edit=event.target.closest?.('[data-dhcp-edit]'); if(edit) return openIdentityReservation('edit', edit.dataset.dhcpEdit, edit.dataset.dhcpIp); const remove=event.target.closest?.('[data-dhcp-remove]'); if(remove) return openIdentityReservation('remove', remove.dataset.dhcpRemove); if(event.target.closest?.('[data-identity-claim-cancel]')) return closeIdentityClaim(); if(event.target.closest?.('[data-identity-reservation-cancel]')) return closeIdentityReservation(); if(event.target.closest?.('[data-identity-claim-save]')) return saveIdentityClaim(); if(event.target.closest?.('[data-identity-reservation-save]')) return saveIdentityReservation(); if(event.target.closest?.('[data-dhcp-refresh],[data-dns-refresh]')) return hydrateIdentity(); },true);
"####
}
